// Step 1: Reproduce - identify consistent input that triggers the bug
@Service
public class OrderService {
    private final CustomerRepository customerRepo;

    public Order createOrder(Long customerId, String item) {
        // Step 2: Isolate - add logging to narrow down where it fails
        log.info("Creating order for customer: {}", customerId);
        var customer = customerRepo.findById(customerId).orElse(null);
        log.info("Found customer: {}", customer); // Reveals null here!

        // Step 3: Hypothesize - customer might not exist in DB
        if (customer == null) {
            throw new IllegalArgumentException("Customer not found: " + customerId);
        }

        var order = new Order(customer.getId(), item);
        log.info("Order created successfully: {}", order);
        return order; // Step 4: Verify with test for missing customer
    }
}

// Explaining this code to a rubber duck might sound like:
// "Okay duck, I'm trying to find the first order over 100 dollars.
// I loop through all orders... wait, why am I returning inside the loop?"
@Service
public class OrderAnalyzer {
    public Order findFirstExpensiveOrder(List<Order> orders) {
        for (var order : orders) {
            if (order.amount() > 100) {
                return order; // "Oh! I return here immediately..."
            }
        }
        // "But if the first order is under 100, I return null!
        // I never check the rest of the orders. That's the bug!"
        return null;
    }

    // Fixed version after explaining to the duck:
    public Optional<Order> findFirstExpensiveOrderFixed(List<Order> orders) {
        return orders.stream()
            .filter(order -> order.amount() > 100)
            .findFirst(); // Now it checks ALL orders
    }
}

@Service
public class OrderProcessor {
    private final PaymentService paymentService;

    public void processOrder(Order order) {
        // Assumption 1: order is never null (should validate)
        log.info("Processing order: {}", order);

        // Assumption 2: payment service always returns a result
        var payment = paymentService.processPayment(order.amount());
        log.info("Payment result: {}", payment); // Check: is it null?

        // Assumption 3: payment has a status field
        if (payment.status().equals("SUCCESS")) { // NPE if payment is null!
            order.markAsPaid();
        }

        // Fixed version that checks assumptions explicitly:
        if (payment == null || payment.status() == null) {
            log.error("Payment failed: null result from payment service");
            throw new PaymentException("Payment processing returned null");
        }
    }
}

@RestController
public class UserController {
    private final UserService userService;

    @GetMapping("/user/{id}")
    public User getUser(@PathVariable Long id) {
        // MISTAKE 1: Catching exception without investigating why it happens
        try {
            return userService.findById(id);
        } catch (Exception e) {
            return null; // Hides the real problem!
        }

        // MISTAKE 2: Adding null check without finding why it's null
        var user = userService.findById(id);
        if (user != null) { // Why is it null? DB issue? Wrong ID?
            return user;
        }
        return new User(); // Returns empty user instead of proper error

        // CORRECT: Investigate root cause and handle properly
        return userService.findById(id)
            .orElseThrow(() -> new UserNotFoundException("User not found: " + id));
    }
}

// Developer explaining to a rubber duck:
// "So duck, I have this method that calculates shipping costs..."
@Service
public class ShippingCalculator {
    public BigDecimal calculateShipping(Order order) {
        var baseRate = new BigDecimal("10.00");
        var weight = order.totalWeight(); // "Order total weight..."

        // "If weight is over 5 kilograms, I add 2 dollars per kilo..."
        if (weight > 5) {
            var extraCharge = weight * 2; // "Wait, weight times 2..."
            // "Oh no! weight is a double but I'm multiplying by int 2
            // and assigning to int extraCharge! That's losing precision!"
            return baseRate.add(new BigDecimal(extraCharge));
        }

        // Fixed after explaining to the duck:
        if (weight > 5) {
            var extraCharge = new BigDecimal(weight).multiply(new BigDecimal("2.00"));
            return baseRate.add(extraCharge); // Proper decimal math now
        }
        return baseRate;
    }
}

// Step 1: Reproduce - found that POST /orders with empty items fails
@RestController
public class OrderController {
    private final OrderService orderService;

    @PostMapping("/orders")
    public Order createOrder(@RequestBody OrderRequest request) {
        // Step 2: Read error - stack trace points to this line
        log.info("Creating order: {}", request); // Step 4: Check what we receive

        // Step 3: Isolate - narrow down to item processing
        var items = request.items();
        log.info("Processing {} items", items.size()); // Empty list? Null?

        // Step 5: Trace execution - inspect values at failure point
        if (items == null || items.isEmpty()) {
            log.error("Order request has no items"); // Found it!
            throw new IllegalArgumentException("Order must have at least one item");
        }

        return orderService.createOrder(items);
    }
}
